// The private income tax must match Skatteverket's own calculator ("Räkna ut din skatt")
// to the krona, for every component. Cases are generated by tools/skatteverket/fetch-cases.mjs.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { privateIncomeTax, getBrytpunkt } from '../../js/engine.js';
import { fixtureData } from '../helpers/data.mjs';

const { cases } = JSON.parse(readFileSync(new URL('../fixtures/skatteverket-cases.json', import.meta.url), 'utf8'));

// Fields compared (same names in the engine result and in the fixture's `expected`).
const FIELDS = [
  'grundavdrag', 'kommunalSkatt', 'statligSkatt', 'burialSkatt', 'churchSkatt', 'publicServiceSkatt',
  'allmanPensionsAvgift', 'jobbskatteavdrag', 'skattereduktionForvarvsinkomst', 'tillfalligSkattereduktion',
  'incomeTax',
];

const byYear = Map.groupBy(cases, (c) => c.input.year);
for (const [year, yearCases] of byYear) {
  test(`private income tax matches Skatteverket, ${year} (${yearCases.length} cases)`, () => {
    for (const c of yearCases) {
      const r = privateIncomeTax(c.input, fixtureData);
      const age = c.input.year - c.input.yearBorn - 1;
      for (const k of FIELDS) {
        assert.equal(r[k], c.expected[k], `${k}, age ${age}, income ${c.input.income}: ${JSON.stringify(c.input)}`);
      }
    }
  });
}

// Brytpunkt published by Skatteverket (and spiris.se for 2020-2024).
// https://www.skatteverket.se/privat/etjansterochblanketter/svarpavanligafragor/inkomstavtjanst/privattjansteinkomsterfaq/narskamanbetalastatliginkomstskattochhurhogarden.5.10010ec103545f243e8000166.html
const PUBLISHED_BRYTPUNKT = {
  2020: [523200, 575500], 2021: [537200, 596800], 2022: [554900, 618700], 2023: [613900, 683200],
  2024: [615300, 697300], 2025: [643100, 733200], 2026: [660400, 760500],
};

test('computed brytpunkt equals published values', () => {
  for (const [year, [ordinary, forhojt]] of Object.entries(PUBLISHED_BRYTPUNKT)) {
    assert.equal(getBrytpunkt(Number(year), 'ordinary', fixtureData), ordinary, `${year} ordinary`);
    assert.equal(getBrytpunkt(Number(year), 'forhojt', fixtureData), forhojt, `${year} förhöjt`);
  }
});
